# generated by `python -m assay recompute` from grounding.yaml - do not edit


class AssayVerifierBroken(Exception):
    pass

import json
import os
import re
import socket
import subprocess
from pathlib import Path

TIMEOUT_S = 300
_WORKSPACE = None


def _repo():
    root = os.environ.get("ASSAY_REPO") or _WORKSPACE or "."
    return Path(root)


def _confine(rel):
    root = _repo().resolve()
    full = (root / rel).resolve()
    if full != root and root not in full.parents:
        raise AssertionError("path escapes the repository: %s" % rel)
    return full


def _read(rel):
    p = _confine(rel)
    if not p.is_file():
        raise AssertionError("missing file: %s" % rel)
    return p.read_text(encoding="utf-8", errors="replace")


def _exists(rel):
    return _confine(rel).exists()


def _if_evidence(required=None):
    # This file is written by the host after copying the authored suite. Subject
    # processes cannot traverse the suite-private directory or replace its data.
    path = Path(__file__).with_name("if_evidence.json")
    if not path.is_file():
        raise AssayVerifierBroken("IF evidence is unavailable")
    evidence = json.loads(path.read_text(encoding="utf-8"))
    if evidence.get("schema") != "thanatos.if-evidence/v1":
        raise AssayVerifierBroken("unsupported IF evidence")
    if required in (None, "final_diff", "changed_paths") and (
        evidence.get("diff_error") or evidence.get("changed_paths") is None
    ):
        raise AssayVerifierBroken("complete IF diff evidence is unavailable")
    if required in ("trajectory", "final_answer") and not evidence.get("trajectory_complete"):
        raise AssayVerifierBroken("a complete execution trace is required")
    if required == "final_diff":
        return evidence["diff"]
    if required is not None and evidence.get(required) is None:
        raise AssayVerifierBroken("required IF evidence is unavailable: " + required)
    return evidence if required is None else evidence[required]


def _exists_quiet(rel):
    return _confine(rel).exists()


def _absent(rel):
    return not _confine(rel).exists()


def _scrubbed_env():
    def secret(k):
        ku = k.upper()
        return ((ku.startswith("ASSAY_") and ku != "ASSAY_REPO")
                or any(t in ku for t in ("SECRET", "TOKEN", "PASSWORD", "APIKEY", "API_KEY")))
    env = {k: v for k, v in os.environ.items() if not secret(k)}
    env.setdefault("GOTOOLCHAIN", "local")
    env.setdefault("GOFLAGS", "-mod=readonly")
    env.setdefault("PYTHONPYCACHEPREFIX",
                   os.path.join(os.environ.get("TMPDIR", "/tmp"), "assay_pycache"))
    env["HOME"] = "/tmp"
    env.setdefault("XDG_CACHE_HOME", "/tmp/.cache")
    return env


def _drop_priv():
    # Runs as preexec_fn in the forked child, before exec. When we are root the agent command
    # MUST end up as the unprivileged 'nobody' uid: that drop is the C1 reward-forgery boundary
    # (agent code can never write the root-only /scratch where the junit + reward live). It must
    # FAIL CLOSED. A swallowed drop failure -- e.g. setuid() returning EAGAIN because uid 65534 is
    # at its RLIMIT_NPROC ceiling -- would otherwise exec agent code as ROOT and let it forge the
    # reward. So if the drop raises OR does not verifiably take effect, abort the child with
    # os._exit (never exec the payload) rather than run it privileged.
    if not (hasattr(os, "geteuid") and os.geteuid() == 0):
        return  # already unprivileged: nothing to drop, no privilege to escape
    try:
        try:
            os.setgroups([])
        except Exception:
            pass
        os.setgid(65534)   # nogroup
        os.setuid(65534)   # nobody
    except BaseException:
        os._exit(71)       # drop raised -> refuse to exec agent code as root
    # setuid()/setgid() by root set the real, effective AND saved ids, so every one must now read
    # 'nobody'. A soft failure that left any of them privileged means the drop did not hold: abort.
    try:
        ok = (os.getuid() == 65534 and os.geteuid() == 65534
              and os.getgid() == 65534 and os.getegid() == 65534)
    except BaseException:
        ok = False
    if not ok:
        os._exit(71)       # partial/failed drop -> refuse to exec agent code as root


def _walk_sources(exts, skip_dirs=(), cap=4_000_000):
    import os as _os
    root = _repo().resolve()
    skip = set(skip_dirs) | {".git"}
    for dp, dns, fns in _os.walk(str(root)):
        dns[:] = [d for d in dns
                  if d not in skip and not _os.path.islink(_os.path.join(dp, d))]
        for fn in fns:
            if not any(fn.endswith(e) for e in exts):
                continue
            full = _os.path.join(dp, fn)
            if _os.path.islink(full):
                continue
            try:
                with open(full, encoding="utf-8", errors="replace") as fh:
                    yield _os.path.relpath(full, str(root)), fh.read(cap)
            except OSError:
                continue


def _mark_outcome(name, outcome):
    d = os.environ.get("ASSAY_BROKEN_DIR")
    if not d:
        return
    try:
        with open(os.path.join(d, name), "w", encoding="utf-8") as fh:
            fh.write(os.environ.get("ASSAY_BROKEN_NONCE", "") + ":" + outcome)
    except OSError:
        pass


def _run_remote(argv, socket_path):
    request = json.dumps({"argv": [os.fspath(a) for a in argv]}).encode("utf-8") + b"\n"
    chunks = []
    try:
        with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as conn:
            conn.settimeout(TIMEOUT_S + 15)
            conn.connect(socket_path)
            conn.sendall(request)
            conn.shutdown(socket.SHUT_WR)
            while True:
                chunk = conn.recv(65536)
                if not chunk:
                    break
                chunks.append(chunk)
    except (OSError, ValueError) as exc:
        raise AssayVerifierBroken("trusted subject runner failed: %s" % exc)
    try:
        response = json.loads(b"".join(chunks).decode("utf-8"))
        if not isinstance(response, dict) or response.get("kind") not in {"ok", "broken"}:
            raise ValueError("invalid runner response")
        if response["kind"] == "broken":
            raise AssayVerifierBroken(str(response.get("error") or "subject runner failed"))
        if set(response) != {"kind", "returncode", "output"}:
            raise ValueError("invalid runner response fields")
        return int(response["returncode"]), str(response.get("output") or "")
    except AssayVerifierBroken:
        raise
    except (UnicodeDecodeError, ValueError, TypeError, json.JSONDecodeError) as exc:
        raise AssayVerifierBroken("trusted subject runner returned malformed data: %s" % exc)


def _run(argv):
    runner_socket = os.environ.get("ASSAY_RUN_SOCKET")
    if runner_socket:
        return _run_remote(argv, runner_socket)
    try:
        p = subprocess.run(
            argv, cwd=str(_repo()), capture_output=True, text=True,
            timeout=TIMEOUT_S, env=_scrubbed_env(),
            preexec_fn=(_drop_priv if os.name == "posix" else None),
        )
    except FileNotFoundError as exc:
        raise AssayVerifierBroken(
            "%s is not installed on the grading machine (%s)" % (argv[0], exc)
        )
    except subprocess.TimeoutExpired:
        raise AssayVerifierBroken(
            "%s timed out after %ss; a slow machine is not a failed submission"
            % (argv[0], TIMEOUT_S)
        )
    return p.returncode, (p.stdout or "") + (p.stderr or "")


