def test_v_07():
    try:
        import ast
        offenders = []
        for path in ("src/currency.py", "src/news.py"):
            tree = ast.parse(_read(path))
            for node in ast.walk(tree):
                if not isinstance(node, ast.Call):
                    continue
                fn = node.func
                dotted_run = isinstance(fn, ast.Attribute) and fn.attr == "run" and isinstance(fn.value, ast.Name) and fn.value.id in {"asyncio", "anyio"}
                loop_run = isinstance(fn, ast.Attribute) and fn.attr == "run_until_complete"
                imported_run = isinstance(fn, ast.Name) and fn.id in {"run", "run_until_complete"}
                if dotted_run or loop_run or imported_run:
                    offenders.append((path, node.lineno))
        assert offenders
        _mark_outcome('test_v_07', "passed")
    except AssayVerifierBroken as _avb:
        _mark_outcome('test_v_07', "broken")
        raise AssertionError("ASSAY_BROKEN " + str(_avb))
    except AssertionError as _ae:
        _mark_outcome('test_v_07', "absent" if 'missing file:' in str(_ae) else "failed")
        raise
    except BaseException as _e:
        _mark_outcome('test_v_07', "broken")
        raise AssertionError("ASSAY_BROKEN body error: " + repr(_e))

